+import { LINEAR_UNITS, TEMPERATURE_UNITS } from "./units.ts";
+
+type Temperature = (typeof TEMPERATURE_UNITS)[number];
+
+function isTemperature(unit: string): unit is Temperature {
+  return (TEMPERATURE_UNITS as readonly string[]).includes(unit);
+}
+
+function kindOf(unit: string): string | undefined {
+  if (isTemperature(unit)) return "temperature";
+  return LINEAR_UNITS[unit]?.kind;
+}
+
+/** Convert a temperature to Celsius, rejecting values below absolute zero in the given unit. */
+function toCelsius(value: number, unit: Temperature): number {
+  switch (unit) {
+    case "C":
+      if (value < -273.15) throw new RangeError(`temperature below absolute zero: ${value} C`);
+      return value;
+    case "F":
+      if (value < -459.67) throw new RangeError(`temperature below absolute zero: ${value} F`);
+      return ((value - 32) * 5) / 9;
+    case "K":
+      if (value < 0) throw new RangeError(`temperature below absolute zero: ${value} K`);
+      return value - 273.15;
+  }
+}
+
+function fromCelsius(celsius: number, unit: Temperature): number {
+  switch (unit) {
+    case "C":
+      return celsius;
+    case "F":
+      return (celsius * 9) / 5 + 32;
+    case "K":
+      return celsius + 273.15;
+  }
+}
